 /* ---------------------------------------------------------------- hjálp */
 function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
 function count(re,s){var m=s.match(re);return m?m.length:0;}
 function part(code,tag){var re=new RegExp('<'+tag+'[^>]*>([\\s\\S]*?)<\\/'+tag+'>','gi'),m,out='';while((m=re.exec(code)))out+=m[1]+'\n';return out;}
 function body(code){var m=code.match(/<body[^>]*>([\s\S]*?)<\/body>/i);return m?m[1]:code;}
 function inner(code,tag){var m=code.match(new RegExp('<'+tag+'[^>]*>([\\s\\S]*?)<\\/'+tag+'>','i'));return m?m[1].replace(/<[^>]+>/g,'').trim():'';}
 function block(css,sel){var re=new RegExp('(^|[\\s,}])'+sel.replace('.','\\.')+'\\s*\\{([^}]*)\\}','i'),m=css.match(re);return m?m[2]:'';}
 function val(css,prop){var m=css.match(new RegExp('(^|[;\\s{])'+prop+'\\s*:\\s*([^;}]+)','i'));return m?m[2].trim().toLowerCase():'';}
 function structure(code){return /<!doctype\s+html>/i.test(code)&&/<html[^>]*>[\s\S]*<\/html>/i.test(code)&&/<head[^>]*>[\s\S]*<\/head>/i.test(code)&&/<body[^>]*>[\s\S]*<\/body>/i.test(code);}
 function closed(code,tag){return count(new RegExp('<'+tag+'(\\s|>)','gi'),code)===count(new RegExp('<\\/'+tag+'>','gi'),code);}
 function copy(text,cb){function ok(){cb&&cb(true);}function no(){try{var t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();document.execCommand('copy');document.body.removeChild(t);ok();}catch(e){cb&&cb(false);}}
  if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(text).then(ok,no);else no();}
 function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}return a;}
