  lab.run=run;
  function persist(){state.code[id]=ta.value;save();savedEl.textContent='goymt';clearTimeout(lab.timer);lab.timer=setTimeout(function(){savedEl.textContent='';},1500);if(!state.tried[id]){state.tried[id]=true;save();refresh();}}
