 function starSvg(n,max){var s='<span class="kv-stars" aria-label="'+n+' av '+max+'">';for(var i=0;i<max;i++)s+='<svg viewBox="0 0 24 24" fill="'+(i<n?'#e5b50a':'#d9d2bf')+'" aria-hidden="true"><use href="#kv-star"/></svg>';return s+'</span>';}
 function mountQuiz(card){var id=card.getAttribute('data-quiz'),qs=QUIZ[id],bodyEl=$('[data-quiz-body]',card),idx=0,score=0,order=[];
  function intro(){var best=state.quiz[id];bodyEl.innerHTML='<div class="kv-quiz__foot"><span>'+qs.length+' spurningar'+(best!=null?' · besta úrslit: '+best+' av '+qs.length+' '+starSvg(best===qs.length?1:0,1):'')+'</span><button class="kv-btn kv-btn--sm" type="button" data-q-start>'+(best!=null?'Royn umaftur':'Byrja kanningina')+'</button></div>';$('[data-q-start]',bodyEl).addEventListener('click',function(){idx=0;score=0;order=shuffle(qs.map(function(_,i){return i;}));show();});}
  function show(){var q=qs[order[idx]],opts=shuffle(q.a.map(function(t,i){return {t:t,i:i};}));
   bodyEl.innerHTML='<div class="kv-quiz__foot" style="margin:0 0 6px"><span>Spurningur '+(idx+1)+' av '+qs.length+'</span><span>'+score+' rætt</span></div><p class="kv-quiz__q">'+q.q+'</p><div class="kv-quiz__opts">'+opts.map(function(o){return '<button type="button" data-i="'+o.i+'">'+o.t+'</button>';}).join('')+'</div><div class="kv-quiz__fb" data-fb></div><div class="kv-quiz__foot"><span></span><button class="kv-btn kv-btn--sm" type="button" data-q-next hidden>'+(idx+1<qs.length?'Næsti spurningur →':'Sí úrslitið')+'</button></div>';
   $$('.kv-quiz__opts button',bodyEl).forEach(function(b){b.addEventListener('click',function(){var i=+b.getAttribute('data-i'),ok=i===q.ok;$$('.kv-quiz__opts button',bodyEl).forEach(function(x){x.disabled=true;if(+x.getAttribute('data-i')===q.ok)x.classList.add('ok');});if(!ok)b.classList.add('no');else score++;var fb=$('[data-fb]',bodyEl);fb.className='kv-quiz__fb '+(ok?'ok':'no');fb.innerHTML=(ok?'<b>Rætt!</b> ':'<b>Ikki heilt.</b> ')+q.fb;var nx=$('[data-q-next]',bodyEl);nx.hidden=false;nx.focus();});});
   $('[data-q-next]',bodyEl).addEventListener('click',function(){idx++;if(idx<qs.length)show();else end();});}
  function end(){var perfect=score===qs.length,best=state.quiz[id];if(best==null||score>best){state.quiz[id]=score;save();}
   bodyEl.innerHTML='<div class="kv-quiz__res">'+(perfect?'<svg aria-hidden="true"><use href="#kv-x2"/></svg>':'')+'<b>'+score+' av '+qs.length+' rætt</b>'+starSvg(perfect?1:0,1)+'<p style="margin-top:8px">'+(perfect?'Fullkomið! Tú fært stjørnu á steypið fyri hetta stigið.':score>=qs.length-1?'Næstan! Royn umaftur og fá allar rættar – so fært tú stjørnu.':'Les frágreiðingarnar í stiginum umaftur og royn so aftur.')+'</p><div class="kv-task__btns" style="justify-content:center"><button class="kv-btn kv-btn--sm" type="button" data-q-again>Royn umaftur</button></div></div>';
   $('[data-q-again]',bodyEl).addEventListener('click',function(){idx=0;score=0;order=shuffle(qs.map(function(_,i){return i;}));show();});
   if(perfect){var allPerfect=Object.keys(QUIZ).every(function(k){return state.quiz[k]===QUIZ[k].length;});if(allPerfect&&!state.special.x2){state.special.x2=true;save();award('x2');}}refresh();}
  intro();}
 $$('[data-quiz]').forEach(mountQuiz);

