 (function(){var form=$('[data-kv-prompt]'),out=$('[data-kv-prompt-out]'),msg=$('[data-kv-prompt-msg]');if(!form)return;
  function build(){var evni=form.evni.value.trim(),stodi=form.stodi.value,h=$$('input[name="h"]:checked',form).map(function(x){return x.value;}),e=$$('input[name="e"]:checked',form).map(function(x){return x.value;});
   var lines=['Jeg skal lave en enkel HTML-hjemmeside om '+(evni?evni:'[emne]')+'.',stodi];if(h.length){lines.push('Siden skal have:');h.forEach(function(x){lines.push('- '+x);});}e.forEach(function(x){lines.push(x);});
   var txt=lines.join('\n');out.innerHTML=esc(txt).replace('[emne]','<span class="d">[emne – skriva evnið omanfyri]</span>');out.setAttribute('data-txt',txt);}
  form.addEventListener('input',build);form.addEventListener('change',build);build();
  $('[data-kv-prompt-copy]').addEventListener('click',function(){copy(out.getAttribute('data-txt'),function(ok){msg.textContent=ok?'Boðið er kopierað. Set tað inn í SkoleGPT (Ctrl + V).':'Kundi ikki kopiera – merk tekstin og avrita hann á annan hátt.';setTimeout(function(){msg.textContent='';},3500);});});})();

