 function refresh(){var n=doneCount(),pct=Math.round(n/8*100);
  for(var i=1;i<=8;i++){var id='s'+i,d=!!state.done[id],started=!!state.tried[id]||state.quiz[id]!=null;
   var tile=$('[data-tile="'+i+'"]');if(tile){tile.classList.toggle('is-done',d);tile.classList.toggle('is-started',!d&&started);$('.kv-state',tile).textContent=d?'Liðugt':started?'Í gongd':'Ikki byrjað';}
   var sec=$('#kv-s'+i);if(sec)sec.classList.toggle('is-done',d);var nav=$('[data-nav="'+i+'"]');if(nav)nav.classList.toggle('is-done',d);}
  var arc=$('[data-kv-ring-arc]');if(arc)arc.setAttribute('stroke-dashoffset',(163.4*(1-n/8)).toFixed(1));txt('[data-kv-ring-n]',n);txt('[data-kv-ring-t]',n+' av 8 stigum');txt('[data-kv-ring-s]',n===0?'Tú hevur ikki byrjað enn':n===8?'Øll stigini eru liðug!':'Næsta: stig '+nextStig());
  var pg=$('[data-kv-prog]');if(pg)pg.style.setProperty('--pct',pct+'%');txt('[data-kv-prog-t]',pct+' %');
  var dots=document.querySelector('[data-kv-dots]');if(dots){var cur=dots.getAttribute('data-cur');var h='';for(var k=1;k<=8;k++)h+='<i class="'+(state.done['s'+k]?'d':'')+(String(k)===cur?' c':'')+'" title="Stig '+k+'"></i>';dots.innerHTML=h;}
  var wonN=TROPHIES.filter(won).length;txt('[data-kv-skap-n]',wonN+' av '+TROPHIES.length+' steypum');var bp=$('[data-kv-bigprog]');if(bp)bp.style.setProperty('--pct',Math.round(wonN/TROPHIES.length*100)+'%');
  var nx=nextStig(),nb=$('[data-kv-skap-next]');if(nb){if(n===8){txt('[data-kv-skap-t]','Tú hevur klárað øll stigini. Vel nú, hvat tú vilt gera í sandkassanum!');nb.textContent='Til sandkassan';nb.setAttribute('href','#kv-sandkassi');nb.setAttribute('data-go','sandkassi');}else{txt('[data-kv-skap-t]',n===0?'Byrja á stigi 1 fyri at vinna fyrsta steypið.':'Flott! Næsta steyp bíðar í stigi '+nx+'.');nb.textContent=(n===0?'Byrja':'Víðari')+' á stigi '+nx;nb.setAttribute('href','#kv-s'+nx);nb.setAttribute('data-go','stig-'+nx);}
  if(window.kvPageLinks)kvPageLinks();}
  var sk=$('[data-kv-skap]');if(sk)sk.innerHTML=TROPHIES.map(function(t){var w=won(t),q=t.id[0]==='s'?state.quiz[t.id]:null,max=t.id[0]==='s'?QUIZ[t.id].length:0;return '<div class="kv-trophy'+(w?' is-won':'')+'"><svg aria-hidden="true"><use href="#'+t.sym+'"/></svg><span>'+t.n+'</span>'+(max?starSvg(q===max?1:0,1):'')+'<small>'+(w?'Vunnið!':t.how)+'</small></div>';}).join('');}
 function txt(sel,v){var e=$(sel);if(e)e.textContent=v;}
 function nextStig(){for(var i=1;i<=8;i++)if(!state.done['s'+i])return i;return 8;}
 refresh();
 var startBtn=$('[data-kv-start]');if(startBtn){var ns=nextStig();if(doneCount()>0&&doneCount()<8){startBtn.setAttribute('href','#kv-s'+ns);startBtn.setAttribute('data-go','stig-'+ns);startBtn.innerHTML='Halt fram á stigi '+ns+' <svg aria-hidden="true"><use href="#kv-i-arrow"/></svg>';}}
 var pr=$('[data-kv-print]');if(pr)pr.addEventListener('click',function(){window.print();});
 (function(){var b=$('[data-kv-reset]'),armed=false,t;if(!b)return;b.addEventListener('click',function(){if(!armed){armed=true;b.textContent='Ja, strika alt?';b.style.background='#ef2418';b.style.borderColor='#ef2418';t=setTimeout(function(){armed=false;b.textContent='Nullstilla alt';b.style.background='';b.style.borderColor='';},4000);return;}
  clearTimeout(t);state={done:{},quiz:{},special:{},code:{},tried:{}};try{localStorage.removeItem(KEY);}catch(e){}Object.keys(labs).forEach(function(id){labs[id].ta.value=labs[id].start;labs[id].run(false);});Object.keys(CHECKS).forEach(function(id){renderChecks(id,null);var d=$('[data-done="'+id+'"]');if(d)d.hidden=true;});$$('[data-quiz]').forEach(mountQuiz);refresh();armed=false;b.textContent='Nullstilla alt';b.style.background='';b.style.borderColor='';toast.innerHTML='<svg aria-hidden="true"><use href="#kv-i-reset"/></svg><div><b>Alt er nullstillað</b><small>Steyp, kanningar og kota eru strikað á hesi eindini.</small></div>';toast.classList.add('is-on');clearTimeout(toastTimer);toastTimer=setTimeout(function(){toast.classList.remove('is-on');},4000);});})();

